code.java:
import java.util.function.Supplier;
class Solution {
    public Supplier<String> createHelloWorld() {
        Supplier<String> inner = new Supplier<String>() {
            @Override
            public String get() {
                return "Hello World";
            }
        };
        return inner;
    }
}

